def track_expenses():
    """
    A function to help the user track their personal expenses.
    """

    # Initialize an empty dictionary to store expenses
    expenses = {}

    def add_expense(category, amount):
        """
        Add a new expense to the dictionary.
        """
        if category not in expenses:
            expenses[category] = 0

        expenses[category] += amount
        print(f"Added '{category}' expense for ${amount}. Total spending: ${sum(expenses.values())}")

    def remove_expense(category, amount):
        """
        Remove an expense from the dictionary.
        """
        if category in expenses:
            expenses[category] -= amount
            print(f"Removed ${amount} from '{category}' expense. Total spending: ${sum(expenses.values())}")
        else:
            print(f"No such category '{category}' found.")

    def view_expenses():
        """
        Print the total spending for each category.
        """
        print("Expenses:")
        for category, amount in expenses.items():
            print(f"- {category}: ${amount}")
        print(f"Total spending: ${sum(expenses.values())}")

    while True:
        command = input("Enter a command (add, remove, view, or quit): ").lower()

        if command == "add":
            category = input("Enter category: ")
            amount = float(input("Enter amount: $"))
            add_expense(category, amount)

        elif command == "remove":
            category = input("Enter category: ")
            amount = float(input("Enter amount to remove: $"))
            remove_expense(category, amount)

        elif command == "view":
            view_expenses()

        elif command == "quit":
            break

        else:
            print("Invalid command. Please try again.")


if __name__ == "__main__":
    track_expenses()
```

This function allows the user to add, remove, and view their expenses. The `add_expense` function adds a new expense to the dictionary, and the `remove_expense` function removes an existing expense. The `view_expenses` function prints the total spending for each category. The `while` loop allows the user to continue entering commands until they choose to quit.
